macro.command:
/**
 * Teleport targets INTO caster-centered radius (no animation, uses MidiQOL.moveToken)
 * - 選中或 target 好目標後運行宏
 * - 選中(控制)施法者 token（作爲圓心）；若未選中則提示
 * - 點擊落點必須在施法者爲圓心的半徑內；超出會提示並重選
 * - 多目標支持：per-target 或 same-for-all 模式
 */

(async () => {
  const RANGE_FT = 60;       // 傳送範圍（英尺），可按需修改
  const TIMEOUT_MS = 20000;  // 單次點擊超時
  const HIGHLIGHT_COLOR = 0x66ccff;

  // ---------- 幫助函數 ----------
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;
  const gridSize = canvas.grid.size;
  const S = CONST.GRID_SNAPPING_MODES;

  function feetBetweenPts(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y) / gridSize * feetPerSquare;
  }

  function centerToTopLeft(centerPoint, tokenDocOrCanvasToken) {
    // tokenDocOrCanvasToken may be a Canvas.Token object (has document.width) or TokenDocument
    const tokenGridW = Number(tokenDocOrCanvasToken.document?.width ?? tokenDocOrCanvasToken.document?.source?.width ?? tokenDocOrCanvasToken.width ?? tokenDocOrCanvasToken._source?.width ?? 1);
    const tokenGridH = Number(tokenDocOrCanvasToken.document?.height ?? tokenDocOrCanvasToken.document?.source?.height ?? tokenDocOrCanvasToken.height ?? tokenDocOrCanvasToken._source?.height ?? tokenGridW);
    const halfWpx = (tokenGridW * gridSize) / 2;
    const halfHpx = (tokenGridH * gridSize) / 2;
    return { x: Math.round(centerPoint.x - halfWpx), y: Math.round(centerPoint.y - halfHpx), gridW: tokenGridW, gridH: tokenGridH };
  }

  // 返回舞臺上的 token 視覺中心（不用已棄用方法）
  function getTokenCenterPoint(tok) {
    return { x: (tok.center?.x ?? (tok.x + tok.w/2)), y: (tok.center?.y ?? (tok.y + tok.h/2)) };
  }

  // snap 舞臺點到網格“格子中心”
  function snapStagePointToGridCenter(stagePoint) {
    try {
      // BaseGrid#getSnappedPoint(point, behavior) -> 返回中心點（舞臺座標）
      return canvas.grid.getSnappedPoint({ x: stagePoint.x, y: stagePoint.y }, { mode: S.CENTER, resolution: 1 });
    } catch (e) {
      // fallback 簡單四捨五入到最近格點中心
      return { x: Math.round(stagePoint.x / gridSize) * gridSize, y: Math.round(stagePoint.y / gridSize) * gridSize };
    }
  }

  // 檢查指定目標矩形是否與已有 tokens 衝突
  function areaOccupiedByOther(topLeftX, topLeftY, widthPx, heightPx, ignoreId = null) {
    const rectA = new PIXI.Rectangle(topLeftX, topLeftY, widthPx, heightPx);
    return canvas.tokens.placeables.some(t => {
      if (t.id === ignoreId) return false;
      const rectB = new PIXI.Rectangle(t.x, t.y, t.w, t.h);
      return rectA.right  > rectB.left &&
             rectA.left   < rectB.right &&
             rectA.bottom > rectB.top &&
             rectA.top    < rectB.bottom;
    });
  }

  // ---------- 解析施法者與目標 ----------
  const caster = canvas.tokens.controlled[0] ?? token; // 優先使用你控制的 token
  if (!caster) {
    ui.notifications.warn("請先控制（選中）施法者的 Token，再運行此宏");
    return;
  }
  const casterCenter = getTokenCenterPoint(caster);

  // 目標集：優先使用 game.user.targets（玩家 target），否則使用被控制的 tokens（不含 caster）
  let targets = Array.from(game.user.targets ?? []);
  if (targets.length === 0) {
    const ctrl = canvas.tokens.controlled?.filter(t => t.id !== caster.id) ?? [];
    targets = ctrl;
  } else {
    // 如果 targets 包含施法者的 token，移除之
    targets = targets.filter(t => t.id !== caster.id);
  }
  if (targets.length === 0) {
    ui.notifications.warn("請先 target 或選中要傳送的一個或多個目標（目標不能包含施法者）");
    return;
  }

  // 如果多個目標，詢問模式
  let mode = "per-target";
  if (targets.length > 1) {
    const choice = await new Promise(resolve => {
      new Dialog({
        title: "傳送模式",
        content: `<p>檢測到 ${targets.length} 個目標。請選擇：</p>`,
        buttons: {
          per: { label: "爲每個目標分別選擇落點", callback: () => resolve("per-target") },
          same: { label: "爲所有目標選擇同一落點（並驗證每個目標是否允許）", callback: () => resolve("same-for-all") },
          cancel: { label: "取消", callback: () => resolve(null) }
        },
        default: "per"
      }).render(true);
    });
    if (!choice) return ui.notifications.info("已取消傳送");
    mode = choice;
  }

  // ---------- 繪製以施法者爲中心的高亮圓（視覺） ----------
  const maxSquares = Math.max(1, Math.floor(RANGE_FT / feetPerSquare));
  const radiusPx = maxSquares * gridSize;
  const g = new PIXI.Graphics();
  g.lineStyle(2, HIGHLIGHT_COLOR, 0.9);
  g.beginFill(HIGHLIGHT_COLOR, 0.06);
  g.drawCircle(casterCenter.x, casterCenter.y, radiusPx);
  g.endFill();
  g.zIndex = 10000;
  canvas.app.stage.addChild(g);
  ui.notifications.info(`請在施法者高亮圓內選擇落點（最多 ${RANGE_FT} 英尺）。點擊超出或被佔用會提示並重選。`);

  // ---------- 單次點擊並 snap 到格子中心（null 表示超時） ----------
  const getClickedSnappedCenter = (ms) => new Promise(resolve => {
    const handler = (event) => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      try { canvas.app.stage.removeChild(g); } catch(e){}
      let pos = null;
      try { pos = event.data.getLocalPosition(canvas.app.stage); } catch(e) { pos = null; }
      if (!pos) return resolve(null);
      const snap = snapStagePointToGridCenter(pos);
      resolve(snap);
    };
    canvas.app.stage.on("pointerdown", handler);
    setTimeout(() => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      try { canvas.app.stage.removeChild(g); } catch(e){}
      resolve(null);
    }, ms);
  });

  // ---------- 邏輯：per-target 與 same-for-all ----------
  try {
    if (mode === "per-target") {
      for (const tk of targets) {
        // 反覆 prompt 直到爲該目標選到合法位置
        while (true) {
          // 重新加入高亮（上一次可能被移除）
          if (!canvas.app.stage.children.includes(g)) canvas.app.stage.addChild(g);
          const snapped = await getClickedSnappedCenter(TIMEOUT_MS);
          if (!snapped) { ui.notifications.warn("未檢測到點擊，請重試"); continue; }

          // 計算該 snapped 的直線距離到 caster 中心
          const dist = feetBetweenPts(snapped, casterCenter);
          if (dist > RANGE_FT + 0.001) {
            ui.notifications.warn(`所選位置距離施法者 ${Math.round(dist)} 英尺，超出 ${RANGE_FT} 英尺，請重新選擇`);
            continue;
          }

          // 將 snapped center 轉爲目標 token 應有的左上與中心（考慮 token 的格寬高）
          const { x: topLeftX, y: topLeftY, gridW, gridH } = (() => {
            const temp = centerToTopLeft(snapped, tk);
            return { x: temp.x, y: temp.y, gridW: temp.gridW, gridH: temp.gridH };
          })();

          // 碰撞檢測
          const occupied = areaOccupiedByOther(topLeftX, topLeftY, gridW * gridSize, gridH * gridSize, tk.id);
          if (occupied) { ui.notifications.warn(`${tk.name} 的目標格被佔用，請重新選擇`); continue; }

          // 計算傳入 MidiQOL.moveToken 的 center（以格爲單位中心）
          // 當 token grid 大小爲偶數時，center 將位於格線交點；當爲奇數時，center 位於格子中心
          const centerX = Math.round((topLeftX + (gridW * gridSize) / 2));
          const centerY = Math.round((topLeftY + (gridH * gridSize) / 2));

          // 執行瞬移（僅用 MidiQOL.moveToken，第三個參數 false 表示無動畫）
          if (typeof MidiQOL?.moveToken === "function") {
            try {
              await MidiQOL.moveToken(tk, { x: centerX, y: centerY }, false);
              ChatMessage.create({ content: `${tk.name} 已被傳送到選定位置（距施法者 ${Math.round(dist)} 英尺）。` });
              console.log(`teleport: ${tk.name} -> center(${centerX},${centerY}), topLeft(${topLeftX},${topLeftY}), grid ${gridW}x${gridH}`);
              break; // 下一目標
            } catch (e) {
              console.error("RealityCollapse: MidiQOL.moveToken failed", e);
              ui.notifications.error("傳送失敗（檢查控制檯）");
              break; // 跳出該目標的循環
            }
          } else {
            ui.notifications.error("MidiQOL.moveToken 不可用（宏配置爲僅使用該函數進行傳送）");
            return;
          }
        } // per-target loop
      } // for each target
    } else { // same-for-all
      while (true) {
        if (!canvas.app.stage.children.includes(g)) canvas.app.stage.addChild(g);
        const snapped = await getClickedSnappedCenter(TIMEOUT_MS);
        if (!snapped) { ui.notifications.warn("未檢測到點擊，請重試"); continue; }

        const dist = feetBetweenPts(snapped, casterCenter);
        if (dist > RANGE_FT + 0.001) { ui.notifications.warn(`所選位置超出 ${RANGE_FT} 英尺，請重選`); continue; }

        // 需要驗證每個 target 的目標矩形是否被佔用（按其各自體型）
        let failed = false;
        const planned = [];
        for (const tk of targets) {
          const { x: topLeftX, y: topLeftY, gridW, gridH } = centerToTopLeft(snapped, tk);
          const occupied = areaOccupiedByOther(topLeftX, topLeftY, gridW * gridSize, gridH * gridSize, tk.id);
          if (occupied) { ui.notifications.warn(`${tk.name} 的目標格被佔用，選擇不合法，請重選`); failed = true; break; }
          planned.push({ tk, topLeftX, topLeftY, gridW, gridH });
        }
        if (failed) continue;

        // 全部合法，執行傳送
        for (const p of planned) {
          try {
            const centerX = Math.round((p.topLeftX + (p.gridW * gridSize) / 2));
            const centerY = Math.round((p.topLeftY + (p.gridH * gridSize) / 2));
            await MidiQOL.moveToken(p.tk, { x: centerX, y: centerY }, false);
            ChatMessage.create({ content: `${p.tk.name} 已被傳送到共同位置（距施法者 ${Math.round(feetBetweenPts({x:centerX,y:centerY}, casterCenter))} 英尺）。` });
            console.log(`teleport same-for-all: ${p.tk.name} -> center(${centerX},${centerY})`);
          } catch (e) {
            console.error("RealityCollapse: MidiQOL.moveToken failed", e);
            ChatMessage.create({ content: `${p.tk.name} 傳送失敗（查看控制檯）` });
          }
        }
        break;
      } // same-for-all while
    }
  } finally {
    try { canvas.app.stage.removeChild(g); } catch(e){}
  }

  console.log("RealityCollapse: caster-centered teleport finished");
})();
